import React from 'react';
import { FaPhoneAlt, FaCalendarCheck } from 'react-icons/fa';
import site from '../data/site';
import ctaBg from '../images/cta-bg.jpg';
import * as s from './CtaBand.module.css';

/**
 * The closing ask, over a photo. The scrim is heavy enough that every word
 * clears AA on the darkest frame of the image, not just the average of it.
 */
export default function CtaBand() {
  return (
    <section className={s.section} id="contact">
      <img className={s.bg} src={ctaBg} alt="" aria-hidden="true" loading="lazy" />
      <div className={s.scrim} aria-hidden="true" />

      <div className={`container ${s.inner}`}>
        <h2 className={s.title}>{site.cta.title}</h2>
        <p className={s.sub}>{site.cta.sub}</p>

        <div className={s.actions}>
          <a className={s.primary} href={site.phoneHref}>
            <FaPhoneAlt aria-hidden="true" /> Call {site.phone}
          </a>
          <a className={s.secondary} href={site.emailHref}>
            <FaCalendarCheck aria-hidden="true" /> Request Free Quote
          </a>
        </div>
      </div>
    </section>
  );
}
