import React from 'react';
import { FaPhoneAlt, FaEnvelope, FaMapMarkerAlt, FaFacebookF, FaYelp } from 'react-icons/fa';
import site from '../data/site';
import logo from '../images/logo.png';
import * as s from './Footer.module.css';

const NAV = [
  { label: 'Home', href: '#top' },
  { label: 'Services', href: '#services' },
  { label: 'About', href: '#about' },
  { label: 'Our Work', href: '#work' },
  { label: 'Contact', href: '#contact' },
];

export default function Footer() {
  const year = new Date().getFullYear();

  return (
    <footer className={s.footer}>
      <div className="container">
        <div className={s.grid}>
          <div>
            {/* Runs large here - the footer column is the roomiest place the
                mark appears, so the lettering inside it is actually readable. */}
            <img className={s.logo} src={logo} alt={`${site.businessName} logo`} loading="lazy" />
            <p className={s.desc}>{site.footer.description}</p>
            <div className={s.social}>
              {site.links.facebook && (
                <a href={site.links.facebook} aria-label="Facebook" target="_blank" rel="noreferrer noopener">
                  <FaFacebookF />
                </a>
              )}
              {site.links.yelp && (
                <a href={site.links.yelp} aria-label="Yelp" target="_blank" rel="noreferrer noopener">
                  <FaYelp />
                </a>
              )}
            </div>
          </div>

          <div>
            <h3 className={s.title}>Quick Links</h3>
            <ul className={s.links}>
              {NAV.map((item) => (
                <li key={item.label}>
                  <a href={item.href}>{item.label}</a>
                </li>
              ))}
            </ul>
          </div>

          <div>
            <h3 className={s.title}>Services</h3>
            <ul className={s.links}>
              {site.services.map((item) => (
                <li key={item.title}>
                  <a href="#services">{item.title}</a>
                </li>
              ))}
            </ul>
          </div>

          <div>
            <h3 className={s.title}>Contact</h3>
            <ul className={s.contact}>
              <li>
                <a href={site.phoneHref}>
                  <FaPhoneAlt aria-hidden="true" /> {site.phone}
                </a>
              </li>
              <li>
                <a href={site.emailHref}>
                  <FaEnvelope aria-hidden="true" /> <span className={s.emailText}>{site.email}</span>
                </a>
              </li>
              <li>
                <span>
                  <FaMapMarkerAlt aria-hidden="true" /> {site.address}
                </span>
              </li>
            </ul>
          </div>
        </div>

        <div className={s.bottom}>
          <p>
            &copy; {year} {site.businessName}. All rights reserved.
          </p>
          <p className={s.tagline}>{site.tagline}</p>
        </div>
      </div>
    </footer>
  );
}
