import React from 'react';
import {
  FaHardHat,
  FaRulerCombined,
  FaLayerGroup,
  FaTools,
  FaArrowRight,
} from 'react-icons/fa';
import site from '../data/site';
import images from '../lib/images';
import * as s from './Services.module.css';

/** `icon` keys from src/data/site.js. Unknown keys fall back to the toolset. */
const ICONS = {
  frame: FaRulerCombined,
  siding: FaLayerGroup,
  remodel: FaTools,
};

export default function Services() {
  return (
    <section className={s.section} id="services">
      <div className="container">
        <header className={s.head}>
          <span className={s.tag}>
            <FaHardHat aria-hidden="true" /> Our Expertise
          </span>
          <h2 className={s.title}>What We Do</h2>
          <p className={s.sub}>
            We offer an extensive range of residential and commercial construction services, all delivered with the same commitment to quality craftsmanship.
          </p>
        </header>

        <div className={s.grid}>
          {site.services.map((item) => {
            const Icon = ICONS[item.icon] || FaTools;
            return (
              <article className={s.card} key={item.title}>
                <div className={s.media}>
                  <div className={s.mediaFrame}>
                    <img
                      src={images[item.image]}
                      alt={`${item.title} work by ${site.businessName}`}
                      loading="lazy"
                    />
                  </div>
                  <span className={s.icon} aria-hidden="true">
                    <Icon />
                  </span>
                </div>

                <div className={s.body}>
                  <h3 className={s.cardTitle}>{item.title}</h3>
                  <p className={s.cardText}>{item.description}</p>
                  <a className={s.link} href="#contact">
                    Get a quote <FaArrowRight aria-hidden="true" />
                  </a>
                </div>
              </article>
            );
          })}
        </div>
      </div>
    </section>
  );
}
