import React from 'react';
import { FaPhoneAlt, FaEnvelope, FaMapMarkerAlt } from 'react-icons/fa';
import site from '../data/site';
import * as s from './TopBar.module.css';

/**
 * The slim contact strip above the nav. Phone and email are the two things a
 * homeowner actually came for, so they sit first and stay tappable.
 */
export default function TopBar() {
  return (
    <div className={s.bar}>
      <div className={`container ${s.inner}`}>
        <div className={s.group}>
          <a className={s.link} href={site.phoneHref}>
            <FaPhoneAlt aria-hidden="true" />
            <span>{site.phone}</span>
          </a>
          <span className={s.divider} aria-hidden="true" />
          <a className={s.link} href={site.emailHref}>
            <FaEnvelope aria-hidden="true" />
            <span className={s.email}>{site.email}</span>
          </a>
        </div>

        <div className={s.group}>
          <span className={s.muted}>
            <FaMapMarkerAlt aria-hidden="true" />
            <span>Serving {site.serviceArea}</span>
          </span>
          <span className={s.divider} aria-hidden="true" />
          <span className={s.tagline}>{site.tagline}</span>
        </div>
      </div>
    </div>
  );
}
